sql.governed:
CREATE OR REPLACE VIEW {{CHECKED}} AS
SELECT *, CASE
  WHEN balance IS NULL THEN 'Missing balance'
  WHEN balance < 0 THEN 'Negative balance'
  WHEN state IS NULL OR state NOT IN ('VA','FL','NJ') THEN 'Invalid state'
  WHEN status IS NULL OR status NOT IN ('Current','Delinquent','Paid') THEN 'Invalid status'
  ELSE 'PASS' END AS quality_result
FROM {{RAW}};

CREATE OR REPLACE VIEW {{ACCEPTED}} AS
SELECT loan_id, balance, state, status FROM {{CHECKED}} WHERE quality_result='PASS';

CREATE OR REPLACE VIEW {{EXCEPTIONS}} AS
SELECT * FROM {{CHECKED}} WHERE quality_result <> 'PASS';

SELECT COUNT(*) AS exceptions FROM {{EXCEPTIONS}};

sql.state_summary:
-- Replaces only this guide's named training summary table.
CREATE OR REPLACE TABLE {{SUMMARY}} USING DELTA AS
SELECT state, COUNT(*) AS accepted_loans, SUM(balance) AS total_balance
FROM {{ACCEPTED}} GROUP BY state;

SELECT * FROM {{SUMMARY}} ORDER BY state;

