sql.projection:
-- A projection exercise; it does not grant or revoke anyone's access.
CREATE OR REPLACE VIEW {{CONSUMER}} AS
SELECT loan_id, state FROM {{ACCEPTED}} WHERE state='VA';

SELECT * FROM {{CONSUMER}} ORDER BY loan_id;
SELECT COUNT(*) AS visible_rows FROM {{CONSUMER}};

